// Cloudflare Pages Function: /mcp — a read-only MCP server (Streamable HTTP).
//
// Stateless: every POST carries one JSON-RPC message (or a batch) and gets a
// plain application/json reply. No session id, no SSE stream (GET answers 405,
// which the transport spec allows), no authentication — the data is the same
// public catalogue served at /data/exam-catalog.json, which is where the tools
// read it from.
//
// Advertised by public/.well-known/mcp/server-card.json (generated by
// _gen_agent_surface.mjs). Keep SERVER_INFO and the tool list in step with it;
// _verify_agent_surface.mjs checks that they match.

export const SERVER_INFO = { name: 'testpreppilot', title: 'TestPrepPilot exam catalogue', version: '1.0.0' };
export const PROTOCOL_VERSIONS = ['2025-11-25', '2025-06-18', '2025-03-26'];
const SITE = 'https://testpreppilot.com';
const MAX_RESULTS = 25;

const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Accept, Mcp-Protocol-Version, Mcp-Session-Id',
};

export const TOOLS = [
  {
    name: 'search_exams',
    title: 'Search exams',
    description:
      'Find published U.S. exam, licence and certification guides by keyword (name, acronym, awarding body, topic). Returns the best matches with fee and guide URL.',
    inputSchema: {
      type: 'object',
      properties: {
        query: { type: 'string', description: 'Keywords, e.g. "nclex", "cpa exam", "comptia security".' },
        category: { type: 'string', description: 'Optional category filter, exactly as returned by list_categories.' },
        limit: { type: 'integer', minimum: 1, maximum: MAX_RESULTS, default: 10 },
      },
      required: ['query'],
      additionalProperties: false,
    },
    annotations: { readOnlyHint: true, openWorldHint: false },
  },
  {
    name: 'get_exam',
    title: 'Get exam facts',
    description:
      'Every structured fact for one guide: awarding body, fee, format, questions, length, pass mark, study time, salary range, topics, last-reviewed month, confidence and primary source URL.',
    inputSchema: {
      type: 'object',
      properties: { slug: { type: 'string', description: 'Guide slug from search_exams, e.g. "aama-cma".' } },
      required: ['slug'],
      additionalProperties: false,
    },
    annotations: { readOnlyHint: true, openWorldHint: false },
  },
  {
    name: 'list_categories',
    title: 'List categories',
    description: 'The credential categories in the catalogue, with the number of published guides in each.',
    inputSchema: { type: 'object', properties: {}, additionalProperties: false },
    annotations: { readOnlyHint: true, openWorldHint: false },
  },
];

const INSTRUCTIONS =
  'Facts about U.S. professional exams and certifications. Start with search_exams, then get_exam for the full record. ' +
  'Always carry `reviewed`, `confidence` and `sourceUrl` into an answer, never present a low-confidence figure as exact, ' +
  'and cite the specific guide URL. Free to quote with attribution to TestPrepPilot.';

// ── Data ─────────────────────────────────────────────────────────────
let catalog = null; // cached per isolate; a deploy starts fresh isolates

async function loadCatalog(env, origin) {
  if (catalog) return catalog;
  const res = await env.ASSETS.fetch(new URL('/data/exam-catalog.json', origin));
  if (!res.ok) throw new Error(`catalogue unavailable (${res.status})`);
  const rows = await res.json();
  catalog = rows.map((r) => ({
    ...r,
    // The site serves pages at the slashed URL; the bare form answers 308.
    url: r.url.endsWith('/') ? r.url : r.url + '/',
    markdownUrl: `${SITE}/exams/${r.slug}/index.md`,
  }));
  return catalog;
}

const norm = (s) => String(s || '').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g, ' ').trim();

function searchRows(rows, { query, category, limit }) {
  const terms = norm(query).split(' ').filter(Boolean);
  if (!terms.length) return [];
  const cat = category ? norm(category) : null;
  const scored = [];
  for (const r of rows) {
    if (cat && norm(r.category) !== cat) continue;
    const name = norm(r.name);
    const slug = norm(r.slug);
    const body = norm(r.awardingBody);
    const extra = norm([r.category, ...(r.topics || [])].join(' '));
    let score = 0;
    let matched = 0;
    for (const t of terms) {
      let s = 0;
      if (` ${name} `.includes(` ${t} `) || ` ${slug} `.includes(` ${t} `)) s = 5;
      // One- and two-letter terms ("rn", "ap") only count as whole words;
      // as substrings they match nearly everything.
      else if (t.length < 3) s = 0;
      else if (name.includes(t) || slug.includes(t)) s = 3;
      else if (body.includes(t)) s = 2;
      else if (extra.includes(t)) s = 1;
      if (s) matched++;
      score += s;
    }
    if (!matched) continue;
    if (matched === terms.length) score += 4;
    if (name === norm(query) || slug === norm(query)) score += 10;
    scored.push({ r, score });
  }
  scored.sort((a, b) => b.score - a.score || a.r.name.localeCompare(b.r.name));
  return scored.slice(0, limit).map(({ r }) => ({
    slug: r.slug,
    name: r.name,
    category: r.category,
    awardingBody: r.awardingBody,
    fee: r.fee,
    url: r.url,
  }));
}

// ── Tools ────────────────────────────────────────────────────────────
function toolResult(data) {
  return { content: [{ type: 'text', text: JSON.stringify(data, null, 2) }], structuredContent: data };
}
function toolError(message) {
  return { content: [{ type: 'text', text: message }], isError: true };
}

async function callTool(name, args, ctx) {
  const rows = await loadCatalog(ctx.env, ctx.origin);
  switch (name) {
    case 'search_exams': {
      if (typeof args.query !== 'string' || !args.query.trim()) return toolError('`query` must be a non-empty string.');
      const limit = Math.min(Math.max(parseInt(args.limit ?? 10, 10) || 10, 1), MAX_RESULTS);
      const results = searchRows(rows, { query: args.query, category: args.category, limit });
      return toolResult({ query: args.query, count: results.length, results });
    }
    case 'get_exam': {
      const slug = String(args.slug || '').trim().toLowerCase();
      const row = rows.find((r) => r.slug === slug);
      if (!row) return toolError(`No published guide with slug "${slug}". Use search_exams to find the slug.`);
      return toolResult(row);
    }
    case 'list_categories': {
      const counts = new Map();
      for (const r of rows) counts.set(r.category, (counts.get(r.category) || 0) + 1);
      const categories = [...counts].sort((a, b) => a[0].localeCompare(b[0])).map(([category, guides]) => ({ category, guides }));
      return toolResult({ total: rows.length, categories });
    }
    default:
      return null;
  }
}

// ── JSON-RPC ─────────────────────────────────────────────────────────
const rpcError = (id, code, message) => ({ jsonrpc: '2.0', id: id ?? null, error: { code, message } });

async function handleMessage(msg, ctx) {
  if (!msg || msg.jsonrpc !== '2.0' || typeof msg.method !== 'string') {
    // A response object from the client (it has no method) needs no reply.
    if (msg && msg.jsonrpc === '2.0' && ('result' in msg || 'error' in msg)) return null;
    return rpcError(msg?.id, -32600, 'Invalid Request');
  }
  const isNotification = !('id' in msg);
  const { id, method, params = {} } = msg;

  if (method.startsWith('notifications/')) return null;

  let result;
  switch (method) {
    case 'initialize': {
      const requested = params.protocolVersion;
      result = {
        protocolVersion: PROTOCOL_VERSIONS.includes(requested) ? requested : PROTOCOL_VERSIONS[0],
        capabilities: { tools: { listChanged: false } },
        serverInfo: SERVER_INFO,
        instructions: INSTRUCTIONS,
      };
      break;
    }
    case 'ping':
      result = {};
      break;
    case 'tools/list':
      result = { tools: TOOLS };
      break;
    case 'tools/call': {
      try {
        result = await callTool(params.name, params.arguments || {}, ctx);
      } catch (err) {
        return isNotification ? null : rpcError(id, -32603, `Internal error: ${err.message}`);
      }
      if (!result) return isNotification ? null : rpcError(id, -32602, `Unknown tool: ${params.name}`);
      break;
    }
    default:
      return isNotification ? null : rpcError(id, -32601, `Method not found: ${method}`);
  }
  return isNotification ? null : { jsonrpc: '2.0', id, result };
}

function json(body, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', ...CORS },
  });
}

export async function onRequest({ request, env }) {
  if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers: CORS });
  if (request.method !== 'POST') {
    return new Response('This MCP endpoint accepts JSON-RPC over POST (Streamable HTTP, no SSE stream).\n', {
      status: 405,
      headers: { 'Allow': 'POST, OPTIONS', 'Content-Type': 'text/plain; charset=utf-8', ...CORS },
    });
  }

  let payload;
  try {
    payload = await request.json();
  } catch {
    return json(rpcError(null, -32700, 'Parse error'), 400);
  }

  const ctx = { env, origin: new URL(request.url).origin };
  if (Array.isArray(payload)) {
    if (!payload.length) return json(rpcError(null, -32600, 'Invalid Request'), 400);
    const replies = (await Promise.all(payload.map((m) => handleMessage(m, ctx)))).filter(Boolean);
    return replies.length ? json(replies) : new Response(null, { status: 202, headers: CORS });
  }
  const reply = await handleMessage(payload, ctx);
  return reply ? json(reply) : new Response(null, { status: 202, headers: CORS });
}
